"""
Production "License Plate" label for the Zebra ZT421 (300 dpi) — SINGLE FILE.

Everything is in here: the logo graphics, the label layout, real Code128
barcodes, and the USB print. No other files needed.
    pip install pillow pywin32     (Pillow renders the label, pywin32 prints)

The media feeds narrow-edge first, so the label is rendered then rotated to
print upright. If it comes out upside down, add  --rotate 270.

Usage:
    python label_print.py --list                 list installed printers
    python label_print.py --print                print the trial label (USB)
    python label_print.py --print --rotate 270   flip if it prints upside down
    python label_print.py --print --printer "ZDesigner ZT421-300dpi ZPL"
    python label_print.py --dump label.zpl       write the ZPL to a file
    python label_print.py --preview              save label_preview.png (readable, pre-rotation)

Trial data is SAMPLE below; live data / SQL come in the next phase.
"""

LOGOS = {
    "IMC": (392, 392, "^GFA,19208,19208,49,"),
    "MKT_SHA": (470, 470, "^GFA,27730,27730,59,"),
    "MKT_POL": (470, 470, "^GFA,27730,27730,59,"),
    "MKT_NP": (470, 470, "^GFA,27730,27730,59,"),
    "MKT_TRI": (470, 470, "^GFA,27730,27730,59,"),
    "MKT_PVN": (470, 470, "^GFA,27730,27730,59,"),
    "SHA": (205, 178, "^GFA,4628,4628,26,"),
    "POL": (178, 178, "^GFA,4094,4094,23,"),
    "NP": (198, 178, "^GFA,4450,4450,25,"),
    "TRI": (178, 178, "^GFA,4094,4094,23,"),
    "THISWAYUP": (200, 168, "^GFA,4200,4200,25,"),
    "FRAGILE": (128, 180, "^GFA,2880,2880,16,"),
}


PW, LL = 2007, 1298          # print width, label length (dots)

# ── sample data for the trial print ─────────────────────────────────────────────
SAMPLE = dict(
    station="RP-09", pii="PAXM7FZ", po="PDO-431675", part="1028119-626",
    desc="ASM-VBRKT,RH", qty="108", stack="0", gw="23", wi="O01", rev="A",
    market="SHA", lp="V-0023260722200276", pdate="", worker="",
)

# ── layout: a list of primitive elements, rendered by both back-ends ─────────────
def build_elements(d):
    """Return the label as primitive tuples. `d` = data dict (see SAMPLE)."""
    E = []
    box  = lambda x0, y0, x1, y1, t=4: E.append(("box", x0, y0, x1, y1, t))
    hln  = lambda x0, x1, y, t=3:      E.append(("hln", x0, x1, y, t))
    vln  = lambda x, y0, y1, t=3:      E.append(("vln", x, y0, y1, t))
    txt  = lambda x, y, s, pt:         E.append(("txt", x, y, str(s), pt))
    logo = lambda name, cx, cy:        E.append(("logo", name, cx, cy))
    bc   = lambda x, y, h, s, bw=2:    E.append(("bc", x, y, h, str(s), bw))

    market = "MKT_" + d["market"]   # big destination-market badge (e.g. MKT_SHA)
    if market not in LOGOS:
        market = "MKT_SHA"

    # band dividers (from the wireframe, scaled to 2007 x 1298)
    TS = 150     # top strip bottom
    UB = 750     # upper band bottom
    MB = 1024    # middle band bottom
    V_TOP  = 1196   # Station ID | PII PO
    V_MKT  = 693    # market | handling
    V_HAND = 1010   # handling | info block
    V_POITEM = 453  # production order | item number (inside info block)
    V_STK  = 1034   # stack | quantity
    V_QTY  = 1455   # quantity | revision
    V_REV  = 1726   # revision | WI location
    V_PAL  = 705    # pallet | license plate

    # frame
    box(6, 6, PW - 6, LL - 6, 4)

    # ── TOP STRIP: Station ID | PII PO (full width) ──
    hln(6, PW - 6, TS, 4)
    vln(V_TOP, 6, TS, 3)
    txt(24, 44, d["station"], 66)
    txt(1216, 16, "PII PO:", 28); bc(1420, 50, 72, d["pii"])

    # ── UPPER BAND: market | handling | (production order / item number) ──
    vln(V_MKT, TS, UB, 3)
    logo(market, (6 + V_MKT) // 2, (TS + UB) // 2)
    vln(V_HAND, TS, UB, 3)
    hx = (V_MKT + V_HAND) // 2
    logo("THISWAYUP", hx, 320)
    hln(V_MKT, V_HAND, 470, 2)
    logo("FRAGILE", hx, 620)
    txt(V_HAND + 20, TS + 14, "Production order:", 30)
    txt(V_HAND + 30, TS + 50, d["po"], 72);   bc(V_HAND + 30, TS + 140, 58, d["po"])
    hln(V_HAND, PW - 6, V_POITEM, 2)
    txt(V_HAND + 20, V_POITEM + 12, "Item number:", 30)
    txt(V_HAND + 30, V_POITEM + 48, d["part"], 64); bc(V_HAND + 30, V_POITEM + 128, 56, d["part"])
    txt(V_HAND + 330, UB - 50, d["desc"], 40)   # item description, bottom of cell

    # ── MIDDLE BAND: STACK LIMIT | Quantity | Revision | WI location ──
    hln(6, PW - 6, UB, 4)
    vln(V_STK, UB, MB, 3)
    txt(24, UB + 16, "STACK", 40); txt(24, UB + 58, "LIMIT:", 40)
    txt(500, UB + 6, d["stack"], 120)
    txt(820, UB + 24, "KG", 56); txt(820, UB + 90, "MAX", 56)
    txt(120, UB + 200, "Hop day:", 30); box(330, UB + 200, 368, UB + 238, 3)
    txt(540, UB + 200, "Hop voi:", 30); box(742, UB + 200, 780, UB + 238, 3)
    vln(V_QTY, UB, MB, 3)
    txt(V_STK + 20, UB + 16, "Quantity:", 32); txt(V_STK + 210, UB + 6, d["qty"], 76)
    bc(V_STK + 20, UB + 120, 60, d["qty"])
    vln(V_REV, UB, MB, 3)
    txt(V_QTY + 20, UB + 16, "Revision:", 30); txt(V_QTY + 20, UB + 58, d["rev"], 56)
    txt(V_REV + 20, UB + 16, "WI location", 30); txt(V_REV + 20, UB + 58, d["wi"], 56)

    # ── BOTTOM BAND: PALLET G.W | License plate ──
    hln(6, PW - 6, MB, 4)
    vln(V_PAL, MB, LL - 6, 3)
    txt(24, MB + 16, "PALLET", 40); txt(24, MB + 58, "G.W:", 40)
    txt(330, MB + 28, d["gw"], 120); txt(560, MB + 150, "KG", 56)
    txt(V_PAL + 20, MB + 14, "License plate:", 32)
    txt(V_PAL + 30, MB + 52, d["lp"], 46); bc(V_PAL + 30, MB + 130, 72, d["lp"])
    return E


# ── Rendering back-end (raster → rotated ZPL) ────────────────────────────────────
# The media feeds narrow-edge first (4.327" across the head, 6.689" long), so the
# landscape design has to be rotated 90° to print upright. Rather than juggle
# per-field ZPL rotation (fragile for mixed text/barcode/graphics), we render the
# whole label to a 1-bit image, rotate it, and send it as one ^GF graphic. Barcodes
# are real (scannable) Code128; logos are decoded from the embedded ^GFA.
ROTATE = 90          # degrees to rotate the landscape design for the feed direction

# Code128 (set B) — validated to round-trip; every printable ASCII char is covered.
_C128 = [
"212222","222122","222221","121223","121322","131222","122213","122312","132212","221213",
"221312","231212","112232","122132","122231","113222","123122","123221","223211","221132",
"221231","213212","223112","312131","311222","321122","321221","312212","322112","322211",
"212123","212321","232121","111323","131123","131321","112313","132113","132311","211313",
"231113","231311","112133","112331","132131","113123","113321","133121","313121","211331",
"231131","213113","213311","213131","311123","311321","331121","312113","312311","332111",
"314111","221411","431111","111224","111422","121124","121421","141122","141221","112214",
"112412","122114","122411","142112","142211","241211","221114","413111","241112","134111",
"111242","121142","121241","114212","124112","124211","411212","421112","421211","212141",
"214121","412121","111143","111341","131141","114113","114311","411113","411311","113141",
"114131","311141","411131","211412","211214","211232","2331112"]


def _c128_runs(data):
    vals = [104] + [ord(c) - 32 for c in data]     # start B + data
    vals.append((vals[0] + sum(v * i for i, v in enumerate(vals[1:], 1))) % 103)  # checksum
    vals.append(106)                                # stop
    runs = [("s", 10)]                              # quiet zone
    for v in vals:
        for i, wch in enumerate(_C128[v]):
            runs.append(("b" if i % 2 == 0 else "s", int(wch)))
    runs.append(("s", 10))
    return runs


def _draw_barcode(dr, x, y, h, data, mw=3):
    cx = x
    for color, w in _c128_runs(data):
        if color == "b":
            dr.rectangle([cx, y, cx + w * mw - 1, y + h], fill=0)
        cx += w * mw
    return cx - x                                   # total width in dots


def _decode_gfa(name):
    """Rebuild a PIL '1' image from an embedded ^GFA graphic."""
    from PIL import Image
    w, h, gfa = LOGOS[name]
    hexdata = gfa.rsplit(",", 1)[1]
    bpr = (w + 7) // 8
    img = Image.new("1", (w, h), 1)
    px = img.load()
    for row in range(h):
        rowbytes = bytes.fromhex(hexdata[row * bpr * 2:(row + 1) * bpr * 2])
        for col in range(w):
            if rowbytes[col // 8] & (0x80 >> (col % 8)):
                px[col, row] = 0
    return img


def _bold_font(pt):
    from PIL import ImageFont
    for p in ("arialbd.ttf", r"C:\Windows\Fonts\arialbd.ttf",
              "/usr/share/fonts/truetype/liberation/LiberationSans-Bold.ttf",
              "DejaVuSans-Bold.ttf"):
        try:
            return ImageFont.truetype(p, pt)
        except Exception:
            continue
    return ImageFont.load_default()


def render_label_image(d=None):
    """Full landscape label (2007x1298) as a 1-bit PIL image, real barcodes."""
    from PIL import Image, ImageDraw
    d = d or SAMPLE
    img = Image.new("1", (PW, LL), 1)
    dr = ImageDraw.Draw(img)
    for el in build_elements(d):
        k = el[0]
        if k == "box":
            _, x0, y0, x1, y1, t = el; dr.rectangle([x0, y0, x1, y1], outline=0, width=t)
        elif k == "hln":
            _, x0, x1, y, t = el; dr.rectangle([x0, y - t // 2, x1, y + t // 2], fill=0)
        elif k == "vln":
            _, x, y0, y1, t = el; dr.rectangle([x - t // 2, y0, x + t // 2, y1], fill=0)
        elif k == "txt":
            _, x, y, s, pt = el; dr.text((x, y), s, font=_bold_font(pt), fill=0)
        elif k == "logo":
            _, name, cx, cy = el
            w, h, _g = LOGOS[name]; im = _decode_gfa(name)
            img.paste(im, (int(cx - w / 2), int(cy - h / 2)))
        elif k == "bc":
            _, x, y, h, s, bw = el
            _draw_barcode(dr, x, y, h, s)
            dr.text((x, y + h + 4), s, font=_bold_font(24), fill=0)
    return img


def render_mock(d=None, path="label_preview.png"):
    """Save the readable (landscape) render — same pixels that get rotated to print."""
    render_label_image(d).save(path)
    return path


def _gfa_hex(img):
    """1-bit PIL image -> uncompressed ZPL ^GF graphic field."""
    w, h = img.size
    bpr = (w + 7) // 8
    px = img.load()
    out = bytearray()
    for y in range(h):
        row = bytearray(bpr)
        for x in range(w):
            if px[x, y] == 0:                        # black
                row[x // 8] |= (0x80 >> (x % 8))
        out += row
    total = bpr * h
    return f"^GFA,{total},{total},{bpr},{out.hex().upper()}"


def build_zpl(d=None, rotate=None):
    """Rotated, print-ready ZPL for the narrow-feed media (^PW/^LL = physical head).
    `rotate` (0/90/180/270) overrides the ROTATE default — use it to flip the
    label the other way if it comes out upside down, e.g. build_zpl(rotate=270)."""
    from PIL import Image
    d = d or SAMPLE
    deg = ROTATE if rotate is None else rotate
    img = render_label_image(d)
    rot = {90: Image.ROTATE_90, 270: Image.ROTATE_270, 180: Image.ROTATE_180}.get(deg)
    if rot is not None:
        img = img.transpose(rot)
    pw, ll = img.size
    return f"^XA^PW{pw}^LL{ll}^LH0,0\n^FO0,0{_gfa_hex(img)}^FS\n^XZ"


import sys
import argparse

# The exact queue name the Excel macro prints to. Confirm with --list on the PC.
DEFAULT_PRINTER = "ZDesigner ZT421-300dpi ZPL"


def list_printers():
    import win32print
    flags = win32print.PRINTER_ENUM_LOCAL | win32print.PRINTER_ENUM_CONNECTIONS
    printers = win32print.EnumPrinters(flags, None, 1)
    print("Installed printers:")
    for p in printers:
        print("   ", p[2])


def send_raw_zpl(zpl, printer_name):
    """Send raw ZPL bytes to a Windows print queue (RAW datatype = passthrough)."""
    import win32print
    data = zpl.encode("utf-8")
    h = win32print.OpenPrinter(printer_name)
    try:
        job = win32print.StartDocPrinter(h, 1, ("Trial License Plate label", None, "RAW"))
        win32print.StartPagePrinter(h)
        win32print.WritePrinter(h, data)
        win32print.EndPagePrinter(h)
        win32print.EndDocPrinter(h)
        print(f"Sent {len(data)} bytes to '{printer_name}' (job {job}).")
    finally:
        win32print.ClosePrinter(h)


def main():
    ap = argparse.ArgumentParser(description="ZT421 trial label print")
    ap.add_argument("--list", action="store_true", help="list installed printers")
    ap.add_argument("--dump", metavar="FILE", help="write ZPL to FILE and exit")
    ap.add_argument("--preview", action="store_true", help="render label_preview.png")
    ap.add_argument("--print", dest="do_print", action="store_true", help="print the label")
    ap.add_argument("--printer", default=DEFAULT_PRINTER, help="target printer name")
    ap.add_argument("--rotate", type=int, default=None, choices=[0, 90, 180, 270],
                    help="rotation for the feed direction (try 270 if 90 prints upside down)")
    args = ap.parse_args()

    if args.list:
        list_printers(); return
    if args.preview:
        print("wrote", render_mock()); return

    zpl = build_zpl(SAMPLE, rotate=args.rotate)

    if args.dump:
        with open(args.dump, "w", encoding="utf-8") as f:
            f.write(zpl)
        print(f"Wrote {len(zpl)} bytes of ZPL to {args.dump}"); return

    if args.do_print:
        try:
            send_raw_zpl(zpl, args.printer)
        except ImportError:
            print("pywin32 is required to print:  pip install pywin32", file=sys.stderr)
            sys.exit(1)
        return

    ap.print_help()


if __name__ == "__main__":
    main()
